custom_css:
/* ================================================================
 * 正在播放 —— 把酒馆排成一个音乐播放器：角色是歌手，聊天是一张专辑
 *
 * 作者：mangosagocreamwithpomelo（Discord）
 * 设计与实现：Claude Opus 5.5（Anthropic）
 * 借的是流媒体播放器的思路（颜色从封面来、底部播放条、正在播放侧栏），
 * 不含任何播放器的商标、图标或字体。
 *
 * 颜色跟着角色走：主题伴侣扩展读当前角色的头像，取一个主色写进 --np-art。
 * 不装扩展时用 --np-art-default（一块中性灰）。
 * ================================================================ */

@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;700;800;900&family=Noto+Sans+SC:wght@400;500;700;900&display=swap');

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * 文字、面板的颜色在酒馆「用户设置 → 主题颜色」里改。
 * ================================================================ */
html:root {
    /* —— 颜色 —— */
    --np-accent: #2ee26b;          /* 强调色：正在播放的名字、音柱、打开的图标下面的小点 */
    --np-on-accent: #000;          /* 强调色上的字 */
    --np-base: #000;               /* 面板之间的底色 */
    --np-art-default: #535353;     /* 没装扩展、或头像取不到颜色时的封面色 */

    /* —— 字体 —— */
    --np-font: 'Figtree', 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    --np-prose-size: 16px;         /* 正文字号 */
    --np-prose-leading: 1.75;      /* 正文行距 */

    /* —— 电脑版面 —— */
    --np-side: 340px;              /* 左栏（资料库）和右栏（正在播放）的宽度 */
    --np-gap: 8px;                 /* 面板之间的缝 */
    --np-pad: 28px;                /* 正文离聊天面板左右边的距离 */

    /* —— 手机版面 —— */
    --np-m-pad: 14px;              /* 正文离屏幕左右边的距离 */
}

/* ==== themes/nowplaying/base.css ==== */
/* ================================================================
 * 正在播放 · 母版
 * 版面（电脑）：
 *   左栏 #np_lib    资料库 = 角色列表（主题脚本画的）
 *   中间 #sheld     聊天 = 一张专辑：顶上封面 + 大名字（#np_hero），消息像曲目一样带序号
 *   右栏 #np_side   正在播放 = 当前角色的大头像和简介
 *   底部 #form_sheld 播放条：左边正在播放的角色，中间输入框，右边 上一版 / 发送 / 下一版
 * 酒馆的聊天宽度固定成「屏幕宽 - 两栏」，所以酒馆自己的左右面板（AI 设置、角色管理）
 * 打开时正好盖在两栏上。
 * 手机：两栏不画，播放条变成浮在底部、带封面色的一块。
 * ================================================================ */

@property --np-art {
    syntax: '<color>';
    inherits: true;
    initial-value: #535353;
}

@property --np-b1 { syntax: '<percentage>'; inherits: false; initial-value: 40%; }
@property --np-b2 { syntax: '<percentage>'; inherits: false; initial-value: 80%; }
@property --np-b3 { syntax: '<percentage>'; inherits: false; initial-value: 55%; }

:root {
    --np-art: var(--np-art-default);
    --np-on-art: #fff;
    --np-panel: var(--SmartThemeBlurTintColor);
    --np-text: var(--SmartThemeBodyColor);
    --np-sub: var(--SmartThemeEmColor);
    --np-line: var(--SmartThemeBorderColor);
    --np-hover: color-mix(in srgb, var(--SmartThemeBodyColor) 7%, transparent);
    --np-elev: color-mix(in srgb, var(--SmartThemeBodyColor) 9%, var(--SmartThemeBlurTintColor));
    --np-elev-hi: color-mix(in srgb, var(--SmartThemeBodyColor) 15%, var(--SmartThemeBlurTintColor));
    --np-bar: 84px;                 /* 播放条高度，主题脚本按实际高度改 */
    --mainFontFamily: var(--np-font);
    --np-ease: cubic-bezier(.3, 0, 0, 1);
}

/* 换角色时封面色慢慢过渡过去 */
html {
    transition: --np-art 900ms ease;
}

body {
    background: var(--np-base);
    font-family: var(--np-font);
}

#bg1,
#bg_custom {
    opacity: 0 !important;
}

* {
    text-shadow: none !important;
}

/* ---------------- 顶栏 ---------------- */
#top-bar {
    background: var(--np-base);
    box-shadow: none;
    backdrop-filter: none;
}

#top-settings-holder .drawer-icon {
    color: var(--np-sub);
    opacity: 1;
    position: relative;
    transition: color .2s, transform .15s var(--np-ease);
}

#top-settings-holder .drawer-icon:hover {
    color: var(--np-text);
}

#top-settings-holder .drawer-icon:active {
    transform: scale(.92);
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--np-text);
}

/* 打开的那个图标下面一个小点（播放器里「正在用」的记号） */
#top-settings-holder .drawer-icon::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -7px;
    width: 4px;
    height: 4px;
    margin-left: -2px;
    border-radius: 50%;
    background: var(--np-accent);
    transform: scale(0);
    transition: transform .25s var(--np-ease);
}

#top-settings-holder .drawer-icon.openIcon::after {
    transform: scale(1);
}

/* ---------------- 聊天面板 ---------------- */
#sheld {
    background: var(--np-panel);
    border-radius: 8px;
    overflow: hidden;
}

#chat {
    background:
        linear-gradient(to bottom,
            var(--np-art) 0,
            color-mix(in srgb, var(--np-art) 45%, var(--np-panel)) 300px,
            var(--np-panel) 560px) var(--np-panel);
    background-attachment: local;
    padding: 0 var(--np-pad) 32px;
    gap: 2px;
}

/* 专辑头：封面 + 「角色」+ 大名字 + 一行小字 */
#np_hero {
    display: flex;
    align-items: flex-end;
    gap: 24px;
    padding: 64px 0 24px;
    color: var(--np-on-art);
    flex-shrink: 0;
}

#np_hero .np-cover {
    width: clamp(140px, 14vw, 220px);
    aspect-ratio: 1;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 4px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, .5);
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_hero .np-info {
    min-width: 0;
}

#np_hero .np-kicker {
    font-size: 14px;
    font-weight: 500;
}

#np_hero .np-title {
    font-size: clamp(40px, 5vw, 92px);
    font-weight: 900;
    line-height: 1.02;
    letter-spacing: -.03em;
    margin: 4px 0 14px;
    overflow-wrap: anywhere;
}

#np_hero .np-meta {
    font-size: 14px;
    opacity: .82;
}

#np_hero .np-meta b {
    font-weight: 700;
    opacity: 1;
}

/* 专辑头下面那排：大圆按钮 = 继续写 */
#np_actions {
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 8px 0 24px;
    flex-shrink: 0;
}

.np-play {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: var(--np-accent);
    color: var(--np-on-accent);
    font-size: 22px;
    cursor: pointer;
    transition: transform .15s var(--np-ease), filter .15s;
}

.np-play:hover {
    transform: scale(1.05);
    filter: brightness(1.08);
}

.np-play:active {
    transform: scale(.95);
}

.np-play i {
    margin-left: 3px;
}

#np_actions .np-hint {
    color: var(--np-sub);
    font-size: 14px;
}

/* 往下滚以后，顶上一条细栏：封面色 + 小播放钮 + 名字 */
#np_top {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 64px;
    z-index: 35;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 var(--np-pad);
    background: color-mix(in srgb, var(--np-art) 70%, #000);
    color: var(--np-on-art);
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -.01em;
    opacity: 0;
    pointer-events: none;
    transition: opacity .25s;
}

#np_top .np-play {
    width: 40px;
    height: 40px;
    font-size: 15px;
}

html.np-scrolled #np_top {
    opacity: 1;
    pointer-events: auto;
}

/* ---------------- 消息 = 曲目 ---------------- */
#chat .mes {
    position: relative;
    padding: 12px 14px 14px 56px;
    border-radius: 6px;
    background: none;
    transition: background-color .2s;
}

#chat .mes:hover {
    background: var(--np-hover);
}

/* 序号（消息编号）；最新的回复是「正在播放」，序号变成强调色 */
#chat .mes::before {
    content: attr(mesid);
    position: absolute;
    left: 6px;
    top: 26px;
    width: 32px;
    text-align: right;
    font: 500 14px/1 var(--np-font);
    font-variant-numeric: tabular-nums;
    color: var(--np-sub);
}

#chat .mes.last_mes[is_user="false"]::before {
    color: var(--np-accent);
}

/* 生成中：序号换成三根跳动的音柱 */
@keyframes np-b1 { 0%, 100% { --np-b1: 25%; } 50% { --np-b1: 100%; } }
@keyframes np-b2 { 0%, 100% { --np-b2: 90%; } 50% { --np-b2: 30%; } }
@keyframes np-b3 { 0%, 100% { --np-b3: 45%; } 50% { --np-b3: 95%; } }

body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
    content: '';
    left: 24px;
    top: 24px;
    width: 14px;
    height: 14px;
    background:
        linear-gradient(var(--np-accent), var(--np-accent)) 0 100% / 3px var(--np-b1) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 50% 100% / 3px var(--np-b2) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 100% 100% / 3px var(--np-b3) no-repeat;
    animation: np-b1 .8s ease-in-out infinite, np-b2 .65s ease-in-out infinite, np-b3 1s ease-in-out infinite;
}

#chat .mes .mesAvatarWrapper {
    position: static;
}

#chat .mes .avatar {
    width: 44px;
    height: 44px;
    margin-right: 14px;
}

body #chat .mes .avatar img {
    width: 44px;
    height: 44px;
    border-radius: 4px !important;
    object-fit: cover;
    object-position: 50% 18%;
}

#chat .mes .ch_name .name_text {
    font-size: 16px;
    font-weight: 700;
    color: var(--np-text);
    transition: color .3s;
}

#chat .mes.last_mes[is_user="false"] .ch_name .name_text {
    color: var(--np-accent);
}

#chat .mes .timestamp {
    color: var(--np-sub);
    font-size: 13px;
    opacity: 1;
}

/* 消息按钮：悬停那一行才出现 */
#chat .mes .mes_button {
    opacity: .75;
    color: var(--np-sub);
}

#chat .mes .mes_button:hover {
    opacity: 1;
    color: var(--np-text);
}

@media (hover: hover) {
    #chat .mes .mes_buttons {
        opacity: 0;
        transition: opacity .15s;
    }

    #chat .mes:hover .mes_buttons,
    #chat .mes:focus-within .mes_buttons {
        opacity: 1;
    }
}

/* 正文 */
#chat .mes_text {
    font-size: var(--np-prose-size);
    line-height: var(--np-prose-leading);
    font-weight: 400;
    color: var(--np-text);
    padding-right: 8px;
}

/* 对白比正文亮一级、稍粗；心理是灰的；代码是深一级的底 */
#chat .mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-weight: 500;
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--SmartThemeEmColor);
}

#chat .mes_text code {
    background: var(--np-elev);
    color: var(--np-text);
    border-radius: 4px;
    padding: .1em .35em;
    border: 0;
}

#chat .mes_text pre {
    background: var(--np-elev);
    border-radius: 8px;
    border: 0;
}

#chat .mes_text pre code {
    background: none;
    padding: 1em 1.2em;
    line-height: 1.6;
    font-size: 14px;
}

#chat .mes_text blockquote {
    border-left: 3px solid var(--np-accent);
    background: var(--np-hover);
    border-radius: 0 6px 6px 0;
}

/* 主题脚本把左右换版搬到了播放条上，消息里的就不画了 */
html.np-js #chat .mes .swipe_left,
html.np-js #chat .mes .swipe_right,
html.np-js #chat .mes .swipes-counter {
    display: none !important;
}

/* ---------------- 播放条 ---------------- */
#form_sheld {
    position: relative;
}

#send_form {
    background: transparent;
    border: 0;
    border-radius: 0;
    backdrop-filter: none;
}

#nonQRFormItems {
    align-items: center;
    column-gap: 10px;
}

#leftSendForm {
    order: 1;
}

#send_textarea {
    order: 2;
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 22px;
    padding: 11px 18px;
    min-height: 44px;
    font-size: 15px;
    color: var(--np-text);
    transition: background-color .2s, border-color .2s;
}

#send_textarea:hover {
    background: var(--np-elev-hi);
}

/* 酒馆一打开就把光标放进输入框，所以焦点框只淡淡一圈 */
#send_textarea:focus-visible {
    border-color: color-mix(in srgb, var(--np-text) 22%, transparent);
    outline: none;
}

#send_form:has(#send_textarea:focus-visible) {
    border: 0;
    outline: none;
}

#rightSendForm {
    order: 3;
    flex-wrap: nowrap;
    align-items: center;
    gap: 4px;
}

#leftSendForm > div,
#rightSendForm > div {
    color: var(--np-sub);
    opacity: 1;
    transition: color .15s, transform .15s var(--np-ease);
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--np-text);
}

#leftSendForm > div:active,
#rightSendForm > div:active {
    transform: scale(.9);
}

/* 控制钮的顺序：重新生成 · 上一版 · 发送 · 下一版 · 继续 · 代写 */
#np_regen { order: 1; }
#np_prev { order: 2; }
#rightSendForm > #send_but,
#rightSendForm > #mes_stop { order: 3; }
#np_next { order: 4; }
#mes_continue { order: 5; }
#mes_impersonate { order: 6; }
#rightSendForm > div:not(.np-ctl, #send_but, #mes_stop, #mes_continue, #mes_impersonate) { order: 7; }

.np-ctl {
    width: 32px;
    height: 32px;
    display: grid;
    place-items: center;
    font-size: 16px;
    cursor: pointer;
}

.np-ctl.np-off {
    opacity: .35 !important;
    pointer-events: none;
}

/* 发送 = 白色圆形的播放钮；生成中变成暂停（停止） */
#rightSendForm > #send_but,
#rightSendForm > #mes_stop {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    align-items: center;
    justify-content: center;
    background: var(--np-text);
    color: var(--np-base);
    font-size: 16px;
    margin: 0 6px;
}

#rightSendForm > #send_but:hover,
#rightSendForm > #mes_stop:hover {
    color: var(--np-base);
    transform: scale(1.06);
}

#rightSendForm > #send_but:active,
#rightSendForm > #mes_stop:active {
    transform: scale(.94);
}

#send_but::before {
    content: '\f04b';
    margin-left: 2px;
}

/* 停止钮里酒馆自己的图标不要，换成暂停 */
#mes_stop > * {
    display: none !important;
}

#mes_stop::before {
    content: '\f04c';
    font: var(--fa-font-solid);
}

/* 播放条顶边一条进度线；生成中有一段亮光来回走 */
@keyframes np-sweep {
    from { background-position: -40% 0; }
    to { background-position: 140% 0; }
}

#form_sheld::before {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    height: 2px;
    background: var(--np-line);
}

body[data-generating="true"] #form_sheld::before {
    background:
        linear-gradient(90deg, transparent, var(--np-accent), transparent) -40% 0 / 40% 100% no-repeat,
        var(--np-line);
    animation: np-sweep 1.4s linear infinite;
}

/* 播放条左边：正在播放的角色 */
#np_now {
    order: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    white-space: normal;
}

#np_now img {
    width: 56px;
    height: 56px;
    border-radius: 4px;
    object-fit: cover;
    object-position: 50% 18%;
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_now .np-n {
    font-size: 14px;
    font-weight: 600;
    color: var(--np-text);
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#np_now .np-s {
    font-size: 12px;
    color: var(--np-sub);
    line-height: 1.4;
    white-space: nowrap;
}

/* ---------------- 左右两栏 ---------------- */
.np-panel {
    position: fixed;
    top: var(--topBarBlockSize);
    bottom: calc(var(--np-bar) + var(--np-gap));
    width: var(--np-side);
    background: var(--np-panel);
    border-radius: 8px;
    overflow-y: auto;
    z-index: 25;
    color: var(--np-text);
    scrollbar-width: thin;
}

#np_lib {
    left: var(--np-gap);
    padding: 12px 8px;
}

#np_side {
    right: var(--np-gap);
    padding: 16px;
}

.np-panel-head {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 10px 14px;
    font-size: 16px;
    font-weight: 700;
    color: var(--np-text);
}

.np-panel-head i {
    color: var(--np-sub);
    font-size: 20px;
}

.np-chips {
    display: flex;
    gap: 8px;
    padding: 0 10px 12px;
}

.np-chip {
    padding: 6px 12px;
    border-radius: 16px;
    background: var(--np-elev);
    font-size: 13px;
    color: var(--np-text);
}

.np-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 10px;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color .15s;
}

.np-item:hover {
    background: var(--np-hover);
}

.np-item.np-cur {
    background: var(--np-elev);
}

.np-item img {
    width: 48px;
    height: 48px;
    border-radius: 4px;
    object-fit: cover;
    object-position: 50% 18%;
    flex-shrink: 0;
    background: var(--np-elev);
}

.np-item .np-t {
    min-width: 0;
    flex: 1;
}

.np-item .np-n {
    font-size: 15px;
    line-height: 1.35;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.np-item.np-cur .np-n {
    color: var(--np-accent);
}

.np-item .np-s {
    font-size: 13px;
    color: var(--np-sub);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.np-item .np-vol {
    color: var(--np-accent);
    font-size: 14px;
}

/* 右栏：大头像 + 名字 + 关于 */
#np_side .np-big {
    width: 100%;
    aspect-ratio: 1;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 8px;
    display: block;
    background: var(--np-elev);
}

#np_side .np-name {
    font-size: 24px;
    font-weight: 800;
    letter-spacing: -.01em;
    margin: 18px 0 2px;
    line-height: 1.2;
}

#np_side .np-by {
    color: var(--np-sub);
    font-size: 14px;
}

.np-card {
    margin-top: 20px;
    border-radius: 8px;
    background: var(--np-elev);
    overflow: hidden;
}

.np-card .np-card-img {
    height: 120px;
    background: linear-gradient(to bottom, transparent, var(--np-elev)), var(--np-art);
    padding: 16px;
    font-weight: 700;
    font-size: 15px;
    color: var(--np-on-art);
}

.np-card .np-card-body {
    padding: 0 16px 16px;
    font-size: 14px;
    line-height: 1.6;
    color: var(--np-sub);
    display: -webkit-box;
    -webkit-line-clamp: 6;
    -webkit-box-orient: vertical;
    overflow: hidden;
    white-space: pre-line;
}

.np-card .np-card-stat {
    padding: 14px 16px 0;
    font-size: 15px;
    color: var(--np-text);
}

/* ================================================================
 * 电脑
 * ================================================================ */
@media screen and (min-width: 1001px) {
    html:root {
        --sheldWidth: calc(100vw - 2 * var(--np-side) - 4 * var(--np-gap)) !important;
    }

    #top-bar {
        width: 100vw;
    }

    #sheld {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
    }

    #chat {
        max-height: none;
    }

    #form_sheld {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        width: auto;
        margin: 0;
        padding: 12px 16px;
        background: var(--np-base);
        z-index: 40;
    }

    #form_sheld::before {
        left: calc(var(--np-side) + 2 * var(--np-gap));
        right: calc(var(--np-side) + 2 * var(--np-gap));
        top: 2px;
        border-radius: 2px;
    }

    #np_now {
        width: calc(var(--np-side) - var(--np-gap));
    }
}

/* ================================================================
 * 手机
 * ================================================================ */
@media screen and (max-width: 1000px) {
    .np-panel {
        display: none;
    }

    #sheld {
        border-radius: 0;
    }

    #chat {
        padding: 0 var(--np-m-pad) 12px;
    }

    #np_hero {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
        padding: 24px 0 12px;
    }

    #np_hero .np-cover {
        width: 60%;
        max-width: 240px;
        align-self: center;
    }

    #np_hero .np-title {
        font-size: 30px;
        margin: 2px 0 6px;
    }

    #np_top {
        padding: 0 var(--np-m-pad);
        font-size: 17px;
        height: 52px;
    }

    #chat .mes {
        padding: 10px 6px 12px;
    }

    #chat .mes::before {
        content: none;
    }

    #chat .mes .avatar,
    body #chat .mes .avatar img {
        width: 40px;
        height: 40px;
    }

    #chat .mes .avatar {
        margin-right: 12px;
    }

    /* 生成中：音柱挪到名字前面 */
    body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
        content: '';
        left: 58px;
        top: 16px;
    }

    body[data-generating="true"] #chat .mes.last_mes[is_user="false"] .ch_name .name_text {
        padding-left: 20px;
    }

    #np_now {
        display: none;
    }

    #chat {
        max-height: none;
        min-height: 0;
    }

    /* 播放条：浮在底部、带封面色的一块 */
    #form_sheld {
        flex-shrink: 0;
        margin: 0 8px 8px;
        width: auto;
        border-radius: 8px;
        background: color-mix(in srgb, var(--np-art) 62%, #000);
        overflow: hidden;
        padding: 8px 6px 8px 8px;
    }

    #form_sheld::before {
        top: auto;
        bottom: 0;
        left: 8px;
        right: 8px;
        background: rgba(255, 255, 255, .2);
    }

    #send_textarea {
        background: rgba(0, 0, 0, .28);
        color: var(--np-on-art);
        padding: 9px 14px;
        min-height: 40px;
    }

    #send_textarea:hover {
        background: rgba(0, 0, 0, .34);
    }

    #leftSendForm > div,
    #rightSendForm > div {
        color: rgba(255, 255, 255, .78);
    }

    .np-ctl {
        width: 28px;
    }

    #np_regen,
    #mes_impersonate {
        display: none !important;
    }

    #rightSendForm > #send_but,
    #rightSendForm > #mes_stop {
        width: 36px;
        height: 36px;
        margin: 0 2px;
        background: #fff;
        color: #000;
    }
}
